{"content":"import unittest

from tree_building import BuildTree, Node, Record


class BuildTreeTests(unittest.TestCase):
    def test_empty_records(self):
        self.assertIsNone(BuildTree([]))

    def test_root_only(self):
        root = BuildTree([Record(0, 0)])
        self.assertIsInstance(root, Node)
        self.assertEqual(root.node_id, 0)
        self.assertEqual(root.children, [])

    def test_unsorted_example_tree(self):
        records = [Record(i, p) for i, p in
                   [(6, 3), (4, 1), (0, 0), (5, 0), (2, 1), (3, 0), (1, 0)]]
        original = records[:]
        root = BuildTree(records)
        self.assertEqual(records, original)
        self.assertEqual(root.node_id, 0)
        self.assertEqual([node.node_id for node in root.children], [1, 3, 5])
        self.assertEqual([node.node_id for node in root.children[0].children], [2, 4])
        self.assertEqual([node.node_id for node in root.children[1].children], [6])
        leaves = root.children[0].children + root.children[1].children + root.children[2:]
        self.assertTrue(all(node.children == [] for node in leaves))

    def test_invalid_record_ids(self):
        for ids in ([1], [-1, 0], [0, 2], [0, 1, 3], [0, 1, 10]):
            with self.subTest(ids=ids):
                with self.assertRaisesRegex(ValueError, 'IDs must be consecutive'):
                    BuildTree([Record(i, 0) for i in ids])

    def test_duplicate_record_ids(self):
        for ids in ([0, 0], [0, 1, 1, 3], [1, 1]):
            with self.subTest(ids=ids):
                with self.assertRaisesRegex(ValueError, 'Duplicate record ID'):
                    BuildTree([Record(i, 0) for i in ids])

    def test_invalid_root_parent(self):
        for parent_id in (-1, 1, 10):
            with self.subTest(parent_id=parent_id):
                with self.assertRaisesRegex(ValueError, 'Root record ID 0 must have parent ID 0'):
                    BuildTree([Record(0, parent_id)])

    def test_invalid_non_root_parent(self):
        for parent_id in (-1, 1, 2, 10):
            with self.subTest(parent_id=parent_id):
                with self.assertRaisesRegex(ValueError, 'non-negative and smaller'):
                    BuildTree([Record(0, 0), Record(1, parent_id), Record(2, 0)])

    def test_large_reversed_chain(self):
        size = 10000
        root = BuildTree([Record(i, max(0, i - 1)) for i in reversed(range(size))])
        node = root
        for expected_id in range(size):
            self.assertEqual(node.node_id, expected_id)
            if expected_id < size - 1:
                self.assertEqual(len(node.children), 1)
                node = node.children[0]
        self.assertEqual(node.children, [])

    def test_large_reversed_wide_tree(self):
        size = 10000
        root = BuildTree([Record(i, 0) for i in reversed(range(size))])
        self.assertEqual([node.node_id for node in root.children], list(range(1, size)))
        self.assertTrue(all(node.children == [] for node in root.children))


if __name__ == '__main__':
    unittest.main()
